//! Exact derived DATA scope signed in the ordinary native admission. Parsed
//! Policy/Published/Consent values alone cannot grant or dispatch anything.
use super::{model,derived_result_plan::{Arguments,ResultReference},messages::{Cause,Recipient},received_request::Source};
