use serde::{Serialize,Deserialize};
#[derive(Clone,Debug,PartialEq,Eq,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct Origin{pub provider:String,pub adapter:String,pub model:String,pub inference_destination:Destination,pub input_hash:String,pub intent_hash:String,pub completed_at:u64,pub recorded_at:u64}
impl Origin{fn valid(&self)->bool{super::admission::model_id(&self.model)&&super::authority::decode(&self.input_hash).is_some()&&super::authority::decode(&self.intent_hash).is_some()&&self.completed_at>0&&self.completed_at<=self.recorded_at&&self.recorded_at<=8_640_000_000_000_000&&crate::pet_config::integration_pet(&self.provider).is_some()&&self.inference_destination.valid()&&matches!(&self.inference_destination,Destination::Server{provider,endpoint,model}if provider==&self.adapter&&model==&self.model&&reqwest::Url::parse(endpoint).is_ok_and(|u|crate::net::is_loopback_url(&u)))}}
#[derive(Clone,Debug,PartialEq,Eq,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct Policy{pub schema_version:u32,pub consent:super::disclosure_consent::Consent,pub goal_id:String,pub pet_id:String,pub source_revision:String,pub intent_hash:String,pub context_hash:String,pub proposal_hash:String,pub cause:Cause,pub arguments:Arguments,pub origin:Origin,pub recipient:Recipient,pub memory_references:Vec<Reference>,pub source:Source}
#[derive(Clone,Debug,PartialEq,Eq,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct Published{pub schema_version:u32,pub result:ResultReference,pub origin:Origin,pub context_hash:String}
impl Published{pub(super)fn valid(&self)->bool{matches!(self.schema_version,1|2)&&self.result.valid()&&self.origin.valid()&&super::authority::decode(&self.context_hash).is_some()}}
impl Policy{
 pub(super)fn valid(&self)->bool{let hash=|v:&str|super::authority::decode(v).is_some();matches!(self.schema_version,1|2)&&self.consent==super::disclosure_consent::Consent::BoundedResultDisclosure&&model::goal_id(&self.goal_id)&&model::token(&self.source_revision)&&model::key(&self.pet_id)&&[&self.intent_hash,&self.context_hash,&self.proposal_hash].iter().all(|v|hash(v))&&self.arguments.valid()&&self.arguments.result.goal_id==self.goal_id&&self.arguments.result.pet_id==self.pet_id&&self.origin.valid()&&self.origin.intent_hash==self.intent_hash&&model::key(&self.cause.task_id)&&model::key(&self.cause.plan_id)&&model::key(&self.cause.step_id)&&self.recipient.pet_id==self.arguments.to_pet_id&&!self.recipient.name.is_empty()&&self.recipient.name.chars().count()<=40&&hash(&self.recipient.configuration_hash)&&self.source.valid()&&self.source.reference==self.arguments.source&&self.source.sender_pet_id==self.arguments.to_pet_id&&self.source.recipient_pet_id==self.pet_id&&self.arguments.expires_at<=self.source.deadline_at&&self.memory_references.len()<crate::pet_memory::context_model::MAX_SELECTED}
 pub(super)fn matches(&self,g:&model::Record)->bool{self.valid()&&g.id==self.goal_id&&g.spec.owner.pet_id==self.pet_id&&model::fingerprint(&g.spec).ok().as_ref()==Some(&self.intent_hash)&&g.spec.received_from.as_ref().is_some_and(|o|o.body.delegation.is_some()&&o.body.source==self.source&&(self.schema_version==2)==(o.body.schema_version==4))&&g.execution_context.as_ref().is_some_and(|c|c.schema_version==(if self.schema_version==2{6}else{4})&&model::fingerprint(c).ok().as_ref()==Some(&self.context_hash)&&c.memory.as_ref().map(|m|m.references.as_slice()).unwrap_or(&[])==self.memory_references.as_slice())&&g.plans.len()==1&&g.tasks.len()==1&&g.plans[0].id==self.cause.plan_id&&g.plans[0].task_id==self.cause.task_id&&g.plans[0].steps.len()==1&&g.plans[0].steps[0].id==self.cause.step_id&&g.plans[0].steps[0].operation.as_ref().is_some_and(|o|Arguments::parse(o).is_ok_and(|a|a==self.arguments))&&super::plans::fingerprint(g).ok().as_ref()==Some(&self.proposal_hash)&&g.native_plan_revisions.iter().any(|r|r.schema_version==(if self.schema_version==2{3}else{2})&&r.target_revision==self.source_revision&&r.target_proposal_hash==self.proposal_hash&&r.patches.len()==1&&r.patches[0].cause==self.cause)}
 pub(super)fn for_spec(&self,s:&super::admission::AdmissionSpec)->bool{self.valid()&&s.schema_version==(if self.schema_version==2{20}else{14})&&s.source_revision==self.source_revision&&s.goal_id==self.goal_id&&s.owner.pet_id==self.pet_id&&s.intent_hash==self.intent_hash&&s.context_hash==self.context_hash&&s.proposal_hash.as_ref()==Some(&self.proposal_hash)&&s.context.schema_version==(if self.schema_version==2{6}else{4})&&s.context.received_request.as_ref().is_some_and(|r|r.schema_version==(if self.schema_version==2{4}else{2})&&r.source==self.source)&&s.context.memory.as_ref().map(|m|m.references.as_slice()).unwrap_or(&[])==self.memory_references.as_slice()&&s.budget.max_model_calls==0&&s.budget.max_tool_calls==1&&self.arguments.expires_at<=s.budget.deadline_at&&self.arguments.expires_at>s.approved_at}
 pub(super)fn matches_envelope(&self,e:&super::messages::Envelope)->bool{self.valid()&&e.schema_version==(if self.schema_version==2{9}else{6})&&e.derived_result.as_ref()==Some(&self.published())&&e.recipient==self.recipient&&e.cause==self.cause&&e.origin.goal_id==self.goal_id&&e.origin.pet_id==self.pet_id&&e.reply_to.as_ref()==Some(&self.arguments.source)&&e.kind==super::messages::Kind::Reply&&e.text==self.arguments.text&&e.deadline_at==self.arguments.expires_at&&!e.provider_use_authorized}
 pub(super)fn published(&self)->Published{Published{schema_version:self.schema_version,result:self.arguments.result.clone(),origin:self.origin.clone(),context_hash:self.context_hash.clone()}}
}
